<?php use App\Helpers\ViewHelper; use App\Core\Csrf; ?><div class="section-heading"><div><p class="eyebrow">Kho sách</p><h2>Danh sách sách</h2></div><a class="button button-primary" href="/admin/books/create">Thêm sách</a></div><div class="table-wrap"><table class="admin-table"><thead><tr><th>Tên sách</th><th>Tác giả</th><th>Giá bán</th><th>Tồn kho</th><th>Trạng thái</th><th>Thao tác</th></tr></thead><tbody><?php foreach ($books ?? [] as $book): ?><tr><td><?= ViewHelper::escape($book['title']) ?></td><td><?= ViewHelper::escape($book['author']) ?></td><td><?= ViewHelper::money((int)$book['price']) ?></td><td><?= (int)$book['stock_quantity'] ?></td><td><?= ViewHelper::escape(ViewHelper::bookStatus((string)$book['status'])) ?></td><td><div class="action-group"><a class="action-button" href="/admin/books/<?= (int)$book['id'] ?>/edit">Sửa</a><form method="post" action="/admin/books/<?= (int)$book['id'] ?>/delete"><?= Csrf::field() ?><button class="action-button action-button-danger" type="submit">Xóa</button></form></div></td></tr><?php endforeach; ?></tbody></table></div>
